-- GENERATED by infra/bigquery/generate.js from replication-set.json. Do not edit by hand.
-- Learning Loop T07: what Postgres lets Datastream read.
--
-- Run ONCE, as the `postgres` user, AFTER the Cloud SQL flag
-- cloudsql.logical_decoding=on is set (that restarts the database). Safe to run again.
--
--   psql "host=... dbname=supersaas user=postgres" -v reader_password="$PW" -f postgres-setup.sql
--
-- What it does:
--  1. creates role datastream_reader: can log in, can replicate, bypasses row-level security
--     (every table has FORCE RLS, so without BYPASSRLS the first backfill would copy 0 rows)
--  2. gives it SELECT on the listed COLUMNS only (not whole tables): even this role
--     cannot read to_email, message bodies, lead names, etc.
--  3. creates publication expelly_bq listing the same columns (Postgres 15+ column lists),
--     so a column that is not listed never even leaves the database engine
--  4. creates the logical replication slot expelly_bq_slot (the bookmark Datastream resumes from)
\set ON_ERROR_STOP on

SELECT format('CREATE ROLE datastream_reader LOGIN REPLICATION BYPASSRLS PASSWORD %L', :'reader_password')
 WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datastream_reader')
\gexec

GRANT USAGE ON SCHEMA "public" TO datastream_reader;
GRANT SELECT ("id", "timezone") ON "public"."orgs" TO datastream_reader;
